// Metro needs literal asset paths. Keep the browser's approved assets as the source.
const fs = require("fs");
const path = require("path");
const root = path.resolve(__dirname, "../../..");
const out = path.resolve(__dirname, "../src/data/assets.ts");
const groups = {
  pictures: "pendev/icons-r2",
  audio: "src/content/audio",
  sounds: "design/sound/final",
  interfaceAudio: "design/sound/families/sine",
  dombiAudio: "design/sound/dombi/dombi-acted",
};
let code =
  "// Generated by node scripts/generate-assets.js. Do not edit by hand.\n";
for (const [name, dir] of Object.entries(groups)) {
  const base = path.join(root, dir),
    entries = [];
  function walk(folder) {
    for (const entry of fs.readdirSync(folder, { withFileTypes: true })) {
      const full = path.join(folder, entry.name);
      if (entry.isDirectory()) walk(full);
      else if (/\.(png|wav)$/.test(entry.name)) {
        const key = path
          .relative(base, full)
          .replaceAll("\\", "/")
          .replace(/\.(png|wav)$/, "");
        let rel = path.relative(path.dirname(out), full).replaceAll("\\", "/");
        if (!rel.startsWith(".")) rel = "./" + rel;
        entries.push(
          `  ${JSON.stringify(key)}: require(${JSON.stringify(rel)}),`,
        );
      }
    }
  }
  walk(base);
  code += `export const ${name}: Record<string, number> = {\n${entries.sort().join("\n")}\n};\n`;
}
const finalSounds = JSON.parse(
  fs.readFileSync(path.join(root, "design/sound/final/sounds.json"), "utf8"),
);
const family = JSON.parse(
  fs.readFileSync(
    path.join(root, "design/sound/families/families.json"),
    "utf8",
  ),
).families.find((f) => f.id === "sine");
const metadata = Object.fromEntries(
  finalSounds.sounds.map((effect) => [
    effect.name,
    [
      {
        key: effect.name,
        volume: effect.volume,
        step: family.tune[effect.name] || 0,
        family: false,
      },
    ],
  ]),
);
for (const [name, effect] of Object.entries(family.sounds))
  metadata[name] = effect.files.map((file) => ({
    key: file.file.replace(/\.wav$/, ""),
    volume: file.volume,
    step: effect.step || 0,
    family: true,
  }));
code += `export const soundMetadata: Record<string, { key: string; volume: number; step: number; family: boolean }[]> = ${JSON.stringify(metadata, null, 2)};\n`;
const voice = JSON.parse(
  fs.readFileSync(path.join(root, "design/sound/dombi/lines.json"), "utf8"),
).voices.find((v) => v.id === "dombi-acted");
const voiceMetadata = {};
for (const [text, line] of Object.entries(voice.lines)) {
  const wav = fs.readFileSync(path.join(root, groups.dombiAudio, line.file));
  let offset = 12,
    channels = 1,
    rate = 44100,
    bits = 16,
    pcm;
  while (offset + 8 <= wav.length) {
    const chunk = wav.toString("ascii", offset, offset + 4),
      length = wav.readUInt32LE(offset + 4),
      start = offset + 8;
    if (chunk === "fmt ") {
      channels = wav.readUInt16LE(start + 2);
      rate = wav.readUInt32LE(start + 4);
      bits = wav.readUInt16LE(start + 14);
    }
    if (chunk === "data") pcm = wav.subarray(start, start + length);
    offset = start + length + (length % 2);
  }
  if (!pcm || bits !== 16)
    throw new Error("Dombi voice must be PCM16: " + line.file);
  const window = Math.round(rate * 0.095) * channels,
    mouth = [],
    shapes = [5, 3, 6, 4, 8, 3, 5, 1, 6, 4];
  for (let i = 0; i < pcm.length / 2; i += window) {
    let sum = 0,
      count = 0;
    for (let j = i; j < Math.min(i + window, pcm.length / 2); j++) {
      const sample = pcm.readInt16LE(j * 2) / 32768;
      sum += sample * sample;
      count++;
    }
    const amp = Math.min(1, Math.sqrt(sum / count) * 4);
    mouth.push([
      Math.round((i / channels / rate) * 1000),
      amp < 0.07 ? 1 : shapes[Math.round(i / window) % shapes.length],
      Math.round(amp * 100) / 100,
    ]);
  }
  voiceMetadata[text] = {
    key: line.file.replace(/\.wav$/, ""),
    volume: line.volume,
    mouth,
  };
}
code += `export const dombiMetadata: Record<string, { key: string; volume: number; mouth: number[][] }> = ${JSON.stringify(voiceMetadata)};\n`;
fs.mkdirSync(path.dirname(out), { recursive: true });
fs.writeFileSync(out, code);
console.log("Generated the bundled pictures, lesson audio and sound effects.");
